export const edits=[];
const e=(group,key,source,print,reason,sources=[],uncertain=null)=>edits.push({group,key,source,print,reason,sources,uncertain});
export const refs={
 aphids:'https://www.rhs.org.uk/biodiversity/aphids',fly:'https://www.rhs.org.uk/biodiversity/carrot-fly',sclerotinia:'https://www.rhs.org.uk/disease/sclerotinia-disease',swift:'https://www.rhs.org.uk/biodiversity/swift-moth-caterpillars',nutrients:'https://www.rhs.org.uk/prevention-protection/nutrient-deficiencies',bolting:'https://www.rhs.org.uk/vegetables/bolting',storage:'https://www.rhs.org.uk/vegetables/root-vegetables-storing',parsnip:'https://www.rhs.org.uk/vegetables/parsnips/grow-your-own',club:'https://www.rhs.org.uk/disease/club-root',tomato:'https://www.rhs.org.uk/problems/tomatoes-leaf-problems',halo:'https://www.rhs.org.uk/plants/pdfs/plant-trials-and-awards/plant-bulletins/runnerbeans.pdf',anthracnose:'https://ecommons.cornell.edu/server/api/core/bitstreams/9d0f0114-c03d-4865-b4a7-7add7faba540/content'};
let g='carrot_and_parsnip_troubles';
e(g,'carrot_fly',{prevention:'Cover vulnerable crops completely with insect-proof mesh on a rotated bed, securing every edge. Sow thinly to minimise thinning; remove thinnings promptly and avoid bruising nearby plants. If thinning is needed, work carefully in damp conditions and firm disturbed soil afterwards. Carrots sown after mid-May can avoid the first generation; harvesting before late August can avoid the second. Keep parsnips growing steadily, but do not rely on large roots to prevent attack.'},{prevention:'Cover completely with insect-proof mesh on rotated ground. Sow thinly. Carrots sown after mid-May or lifted before late August may avoid peak attacks.'},'Replace unreliable open-topped barrier prescription with RHS complete coverage; retain timing and careful thinning.',[refs.fly]);
e(g,'sclerotinia_rot',{description:'A fungal rot of growing and stored roots. White cottony growth develops over soft, decaying tissue, sometimes with black seed-like resting bodies. In the growing crop the crown and lower leaf stalks may rot. The resting bodies can persist in soil for several years.',treatment:'Remove affected plants and rotten stored roots promptly. Keep infected material out of home compost to avoid returning resting bodies to the garden.',prevention:'Store only sound roots, avoid harvest damage and check stores regularly. Clear infected crop remains and weeds, improve airflow and drainage, and avoid spreading contaminated soil. Plan crop breaks around its broad host range; a two-year break is not a guarantee of clearance.'},{description:'Soft root or crown rot develops white cottony mould, sometimes with black resting bodies. Both growing crops and stored roots can be affected.',treatment:'Remove infected plants and rotten stored roots promptly; keep them out of home compost.',prevention:'Store sound roots and check regularly. Clear infected debris, improve drainage and avoid moving contaminated soil.'},'Replace Cheshunt Compound with removal/hygiene; remove unsupported two-year clearance implication.',[refs.sclerotinia]);
e(g,'motley_dwarf_virus',{name:'Carrot Motley Dwarf',description:'Yellow mottling, reddened outer leaves and stunted growth can indicate carrot motley dwarf, a disease complex involving more than one virus. The carrot-willow aphid transmits the viruses. Seedling infection can greatly reduce yield, but similar discolouration has other causes.',treatment:'Remove badly affected plants after confirming the cause where possible; virus-infected plants cannot be cured.',prevention:'Inspect young growth for aphids, encourage aphid predators and remove damaging colonies by hand where practical. These measures do not guarantee prevention of virus transmission.'},{description:'Yellow mottling, red outer leaves and stunting may indicate carrot motley dwarf, an aphid-transmitted virus complex.',treatment:'Confirm the cause and remove badly affected plants; infected plants cannot be cured.',prevention:'Inspect young growth, encourage aphid predators and remove damaging colonies. Virus spread can still occur.'},'Correct singular-virus identity and replace legacy insecticide prescriptions.',[refs.aphids,'https://dpvweb.net/dpv/showdpv/?dpvno=249']);
e(g,'carrot_willow_aphid',{treatment:'Check young leaves for aphids. Tolerate small colonies on vigorous plants, squash damaging colonies by hand and encourage natural predators.',prevention:'Inspect young crops regularly and maintain steady growth. Aphid management can reduce feeding damage but cannot guarantee prevention of virus transmission.'},{treatment:'Tolerate small colonies; squash damaging colonies and encourage natural predators.',prevention:'Inspect young crops and maintain steady growth. Aphid management cannot guarantee protection from viruses.'},'Replace legacy insecticides; retain virus-risk qualification.',[refs.aphids]);
e(g,'swift_moth',{treatment:'Search the soil beside damaged plants and remove caterpillars found feeding on roots. Discard badly damaged or rotting roots.',prevention:'Check vulnerable plants and remove larvae found during cultivation. Where repeated losses justify it, seek advice on a biological nematode product suitable for the identified pest and soil conditions; follow its temperature and moisture instructions.'},{treatment:'Inspect soil beside damaged roots; hand-remove caterpillars. Discard badly damaged or rotting roots.',prevention:'Check vulnerable plants. For recurring losses, consider suitable biological nematodes with supplier guidance.'},'Replace legacy insecticides with hand removal and qualified RHS biological control.',[refs.swift]);
e(g,'clayburn',{description:'Clayburn is a legacy name for a carrot surface disorder associated in the original notes with patches of clay. Appearance alone does not establish the cause: distinguish surface blemishes from pest injury and active rot.',treatment:'Inspect affected roots and seek identification if damage recurs. Discard roots with active decay.',prevention:'Prepare a well-drained, workable seedbed and avoid compaction. Use a raised bed or container where soil conditions repeatedly prevent good roots.'},{description:'A legacy label for carrot surface damage associated with clay. Check for pest injury or rot before deciding the cause.',treatment:'Inspect affected roots; seek identification for recurring damage. Discard active decay.',prevention:'Prepare well-drained, workable soil; use a raised bed where necessary.'},'Remove unverified harmful-salts mechanism, harmlessness assurance and advice to excavate clay. Retain identity for review.',[refs.parsnip,'https://postharvest.ucdavis.edu/ar/produce-facts-sheets/carrot'],'No authoritative diagnosis for this legacy label was established; no alias or pathogen asserted.');
e(g,'small_roots',{description:'Carrots may remain small because of crowding, dry soil, poor soil structure, unsuitable conditions or damage from pests and disease. Check the expected size and harvest stage of the variety before treating small roots as a problem.',treatment:'Check spacing, moisture and root health. Thin crowded plants carefully and water in dry spells. Feed only where poor fertility is established, using an appropriate organic fertiliser at its recommended rate.',prevention:'Prepare a well-drained seedbed, improve soil structure with mature organic matter well before sowing, avoid compaction and maintain suitable spacing and steady moisture.'},{description:'Crowding, drought, poor soil or pest damage can keep roots small. First check variety and maturity.',treatment:'Check spacing, water and root health. Thin carefully and correct confirmed poor fertility.',prevention:'Prepare workable soil in advance; maintain suitable spacing and steady moisture.'},'Replace automatic repeated feeding and universal deep-digging diagnosis with cause-led advice.',[refs.nutrients,'https://www.rhs.org.uk/vegetables/carrots/grow-your-own']);
e(g,'violet_root_rot',{prevention:'Keep affected roots out of storage. Remove infected roots and avoid moving contaminated soil. The fungus persists in soil and has many hosts; seek advice on a crop break if losses recur.'},{prevention:'Keep affected roots out of storage. Remove infected roots, avoid moving soil and seek crop-break advice if losses recur.'},'Remove certain whole-crop-loss claim and implication that one season clears a persistent disease.','https://www.rhs.org.uk/disease/violet-root-rot'.split());
e(g,'fanging',{description:'Carrot and parsnip roots may fork when the growing tip meets stones or compacted soil, or is damaged. Fresh manure and uneven seedbed conditions can also produce poor-shaped roots.',prevention:'Prepare a workable seedbed, remove larger stones and avoid compaction. Improve soil with mature compost in advance; avoid fresh manure immediately before sowing.'},{description:'Roots fork when tips meet stones, compaction or injury. Fresh manure and uneven seedbeds can contribute.',prevention:'Prepare workable soil, remove larger stones and avoid compaction or fresh manure before sowing.'},'Distinguish fresh manure from mature compost; remove blanket claim that any compost causes fanging.',[refs.parsnip,'https://www.rhs.org.uk/vegetables/carrots/grow-your-own']);
e(g,'old_seed_poor_germination',{description:'Parsnip seed loses viability relatively quickly, but slow or missing emergence can also result from cold or dry soil, deep sowing or seedbed damage. Allow for the growing conditions before deciding a sowing has failed.'},{description:'Old seed, cold or dry soil and deep sowing can all delay or prevent emergence. Check conditions before resowing.'},'Remove unsupported claim that old seed is necessarily likeliest after one month.',[refs.parsnip]);
e(g,'parsnip_rust_fungus',{description:'Rust-coloured or brown damage around a parsnip crown needs diagnosis: staining, canker and other damage can resemble one another. The legacy label does not identify a confirmed rust pathogen.',prevention:'Grow in well-drained soil, avoid root injury and remove decaying crop remains. Seek identification before choosing a long crop break for recurring damage.'},{description:'Rust-coloured crown damage may resemble staining or canker; the precise cause needs confirmation.',prevention:'Improve drainage, avoid root injury and seek a diagnosis before choosing a long crop break.'},'Preserve uncertain identity without unsupported five-year prescription.',[refs.parsnip,'https://www.hortiadvice.dk/uploads/0Uiw7kfH/UKParsnipProductionTomWillVCSJan2023HortiAdvice.pdf'],'No confirmed rust-fungus identity; retained separately from canker pending diagnosis.');
g='bean_and_pea_troubles';
e(g,'anthracnose',{applies_to:['bean_french','bean_runner']},{},'Source describes bean anthracnose; correct pea-only assignment to French/runner beans.',[refs.anthracnose]);
e(g,'halo_blight',{applies_to:['bean_french','bean_runner'],description:"Small water-soaked or brown leaf spots with yellow halos and wet-looking pod lesions can indicate bacterial halo blight of French or runner beans. Seed can carry infection; wet conditions favour spread and badly affected plants are stunted.",prevention:'Buy healthy seed from a reputable supplier. Do not save seed from diseased plants; remove infected debris, rotate crops and avoid handling plants when wet.'},{description:'Water-soaked leaf spots with yellow halos and wet-looking pod lesions may indicate bacterial halo blight.',prevention:'Use healthy bought seed. Remove diseased debris, rotate crops and avoid handling wet foliage.'},'Remove pea host assertion from this bean-specific diagnosis; strengthen seed hygiene.',[refs.halo]);
e(g,'seed_beetle',{applies_to:['pea','bean_broad','bean_french','bean_runner']},{},'Broaden generic seed-beetle entry to the peas and beans explicitly described; do not invent a single species.',[],'Generic label can cover different seed beetles; species identity remains unconfirmed.');
for(const key of ['mice','birds'])e(g,key,{applies_to:['bean_broad','bean_french','bean_runner','pea']},{},'Correct pea-only scope for advice explicitly describing peas and beans.',[refs.halo]);
e(g,'birds',{prevention:'Protect vulnerable seeds and seedlings with securely supported netting or wire guards. Keep netting taut, clear of plants and checked regularly so wildlife cannot become trapped.'},{prevention:'Use securely supported netting or wire guards; keep it taut, clear of plants and check for trapped wildlife.'},'Replace fine cotton-thread barrier with secure guards and wildlife checks.',['https://www.rhs.org.uk/biodiversity/birds']);
e(g,'grey_mould_botrytis',{applies_to:['bean_french','pea']},{},'Correct host scope to the French beans and peas actually described.',['https://www.rhs.org.uk/disease/grey-mould']);
e(g,'no_flowers',{applies_to:['bean_broad','bean_french','bean_runner','pea'],description:'Peas and beans may flower poorly when plants are immature, shaded, drought-stressed or receiving too much nitrogen. Bud-feeding insects can also damage flowers; inspect buds and growing conditions before deciding the cause.'},{description:'Immaturity, shade, drought or excessive nitrogen can delay flowers. Inspect buds for feeding damage.'},'Reconcile prose and crop scope; remove unsupported single likeliest-cause claim.',[refs.nutrients,'https://www.rhs.org.uk/advice/grow-your-own/features/runner-beans']);
e(g,'no_pods',{applies_to:['bean_french','bean_runner'],prevention:'Keep roots moist with mature compost, mulching and thorough watering in dry weather, especially at flowering. Plant tender beans after frost risk, protect flowers from damage and choose varieties suited to local conditions.'},{prevention:'Maintain root moisture, mulch and water during flowering. Plant after frost risk and protect flowers from damage.'},'Retain runner/French bean distinctions; remove unverified flower-colour reliability rule.',['https://www.rhs.org.uk/advice/grow-your-own/features/runner-beans']);
e(g,'powdery_mildew',{description:'White powdery patches develop on pea leaves and sometimes pods, often on late crops. Dry roots, crowded foliage and poor airflow can favour damage; timing varies with the weather.',prevention:'Keep roots evenly moist, support plants and allow airflow. Choose resistant varieties for late sowing where mildew recurs; earlier crops may avoid the worst late-season damage.'},{description:'White powdery patches affect leaves and sometimes pods, often on late crops. Dry roots and crowded growth increase stress.',prevention:'Maintain root moisture and airflow. Choose resistant varieties for late crops where mildew recurs.'},'Remove source-book narration and rigid July cutoff; retain useful seasonal tendency.',['https://www.rhs.org.uk/disease/powdery-mildews']);
g='beetroot_troubles';
e(g,'heart_rot',{description:'Summer wilting, sunken brown patches at the root top and blackened flesh can indicate boron deficiency, especially in dry, light or over-limed soil. Other root problems can resemble it, so confirm the cause before adding nutrients.'},{},'Match cautious diagnosis already present in approved print; preserve boron overdose warning.',[refs.nutrients]);
e(g,'speckled_yellows',{description:'Yellowing between greener veins, inward-rolled leaf edges and later brown patches can occur with manganese deficiency. Similar symptoms have other causes, so confirm the diagnosis and check soil conditions.'},{},'Align master diagnostic certainty with the existing cautious print copy.',[refs.nutrients]);
e(g,'leaf_spot',{description:'Brown spots, sometimes with pale centres that fall out, can disfigure beetroot leaves. Light spotting may have little effect on root yield; extensive loss of foliage can check growth.'},{description:'Brown spots may develop pale centres that fall out. Light spotting may have little effect; severe leaf loss can check growth.'},'Qualify blanket claim that leaf spot never materially affects root yield.',['https://www.rhs.org.uk/disease/leaf-spots']);
g='brassica_troubles';
e(g,'club_root_finger_and_toe',{name:'Clubroot (Finger and Toe)',prevention:'Avoid introducing infected soil or transplants. On affected ground, improve drainage and use resistant varieties where available. Test soil pH and lime only as appropriate: reduced acidity can lessen disease but does not eliminate it. Long rotations help manage risk, but the organism can persist for many years.'},{prevention:'Use clean transplants, improve drainage and consider resistant varieties. Test pH before liming; long rotations do not guarantee clearance.'},'Use standard RHS spelling; replace unrestricted liming and short-break implication with tested risk management.',[refs.club]);
e(g,'heartless_cabbages',{description:'Hearting cabbage varieties can fail to form good heads after drought, poor fertility, inadequate light, overcrowding or root damage. Loose planting can also check establishment; firm soil around roots without compacting the whole bed.'},{description:'Drought, poor fertility, shade, crowding or root damage can prevent firm heads. Check establishment and variety.'},'Separate firm planting from damaging soil compaction.',['https://www.rhs.org.uk/vegetables/cabbages/grow-your-own']);
e(g,'frost',{treatment:'Leave healthy growing points to recover and remove soft, rotting leaves. Firm plants gently if roots have been lifted by frost.'},{treatment:'Allow healthy growing points to recover. Remove rotting leaves and gently re-firm lifted roots.'},'Replace burning as treatment for physiological frost damage.',['https://www.rhs.org.uk/prevention-protection/frost-damage']);
e(g,'cabbage_whitefly',{visual_heading:'Tiny white insects beneath leaves',description:'Tiny white flies and their immature stages feed beneath brassica leaves. Honeydew can support sooty mould, but established plants often tolerate infestations; leafy crops may need closer inspection.'},{description:'Tiny white flies lift from leaf undersides when disturbed. Honeydew may support sooty mould; established plants often tolerate them.'},'Correct moth identity and qualify blanket weakening claim; retain species-specific biological-control caution.',['https://www.rhs.org.uk/biodiversity/cabbage-whitefly']);
e(g,'whiptail',{prevention:'Test soil pH before liming. Correct excessive acidity using a soil-test recommendation before the next cauliflower crop.'},{prevention:'Test pH and correct excessive acidity before the next cauliflower crop.'},'Avoid routine liming without a soil test.',[refs.nutrients]);
g='celery_troubles';
for(const key of ['celery_heart_rot','splitting'])e(g,key,{applies_to:['celery']},{},'Restrict stalk/heart-specific advice to celery; do not apply it to the celeriac root.',[]);
e(g,'bolting',{description:'Celery and celeriac can produce a flower stalk prematurely after cold exposure or checks during young growth. Drought and other stress also reduce crop quality; celery then develops a tough central flowering stalk.'},{description:'Cold exposure or checks during young growth can trigger premature flowering in celery or celeriac.'},'Keep both hosts while removing celery-stalk-only diagnosis for celeriac.',[refs.bolting]);
e(g,'splitting',{prevention:'Maintain even soil moisture through dry spells and avoid excessive nitrogen feeding. Improve soil with mature compost and feed only as needed for steady growth.'},{prevention:'Water steadily, improve soil with mature compost and avoid excessive nitrogen feeding.'},'Remove unsupported high-potash routine feed as a cure for split celery stalks.',['https://www.rhs.org.uk/vegetables/celery/grow-your-own',refs.nutrients]);
g='florence_fennel_troubles';
e(g,'lower_sheath_rot',{description:'Outer bulb sheaths may soften and rot in prolonged wet conditions or when mature bulbs stand too long. Check inside before use; fresh shoots do not show that decaying tissue has recovered.'},{description:'Outer bulb sheaths can soften and rot in wet conditions or after delayed harvest. Check inside before use.'},'Remove unsupported absolute stop-growth/mini-bulb sequence while preserving harvest and discard guidance.',['https://www.rhs.org.uk/vegetables/florence-fennel/grow-your-own']);
g='cucurbit_troubles';
const cucumbers=['cucumber_greenhouse','cucumber_outdoor'];
for(const key of ['poor_yield','gummosis','basal_stem_rot'])e(g,key,{applies_to:['cucumber_greenhouse']},{},'Restrict greenhouse-cucumber-specific prose to its described crop and growing context.',['https://www.rhs.org.uk/vegetables/cucumbers/grow-your-own']);
for(const key of ['black_rot','stem_rot','blotch'])e(g,key,{applies_to:cucumbers},{},'Scope this legacy cucumber presentation without assuming every cucurbit has identical symptoms.',[]);
e(g,'no_fruit',{description:'Courgettes, marrows and squash may fail to set fruit if flowers needing pollination receive too little pollen. Cold weather and stressed roots can also reduce fruit set. Cucumber pollination requirements depend on the variety.'},{description:'Poor pollination, cold weather or stressed roots can prevent fruit set. Cucumber requirements depend on variety.'},'Keep the existing cucumber exception and qualify blanket hand-pollination advice.',['https://www.rhs.org.uk/vegetables/cucumbers/grow-your-own','https://www.rhs.org.uk/vegetables/courgettes/grow-your-own']);
e(g,'poor_yield',{treatment:'Pick cucumbers frequently while tender, maintain even root moisture and feed at the recommended rate as fruit develops. Keep mulch clear of the stem base and check roots and drainage if plants lose vigour.'},{treatment:'Pick frequently, water steadily and feed at the recommended rate. Keep mulch clear of the stem base and check drainage.'},'Resolve conflict between mulching over the stem and basal-rot prevention; remove blanket first-fruit removal.',['https://www.rhs.org.uk/vegetables/cucumbers/grow-your-own']);
e(g,'cucumber_mosaic_virus',{description:'Mottled yellow and green leaves, distortion and stunting can indicate cucumber mosaic virus in cucurbits. Symptoms vary by host and other problems can look similar; badly affected plants may decline severely.',prevention:'Start with healthy plants, remove infected material and control nearby weed hosts. Monitor aphids and encourage natural predators, while recognising that aphid management cannot guarantee prevention of virus transmission. Clean hands and tools after handling suspect plants.'},{description:'Mottled yellow and green leaves, distortion and stunting may indicate cucumber mosaic virus; symptoms need confirmation.',prevention:'Use healthy plants, remove infected material and clean hands and tools. Monitor aphids; virus spread can still occur.'},'Remove unsupported relative susceptibility and guaranteed control implication.',['https://www.rhs.org.uk/disease/cucumber-mosaic-virus']);
e(g,'cucumber_mosaic_virus_on_fruit',{description:'Virus-affected cucurbit fruit may be small, misshapen, mottled or warty. Fruit symptoms alone do not confirm cucumber mosaic virus; check leaves and plant growth too.',treatment:'Remove affected plants after confirming the cause where possible. Discard decaying or unusually bitter fruit and clean hands and tools before handling healthy plants.',prevention:'Follow the cucumber mosaic virus advice: use healthy plants, remove infected material, clean tools and monitor aphids. Aphid management cannot guarantee prevention of virus transmission.'},{description:'Small, distorted, mottled or warty fruit may accompany mosaic virus. Check foliage and growth before diagnosing.',treatment:'Remove affected plants. Discard decayed or unusually bitter fruit and clean hands and tools.',prevention:'Use healthy plants, remove infection and monitor aphids; see Cucumber Mosaic Virus for the leaf symptoms.'},'Retain distinct fruit presentation, remove positional condition-1 reference and unconditional edibility assurance.',['https://www.rhs.org.uk/disease/cucumber-mosaic-virus']);
e(g,'root_rot',{description:'Dark, decaying roots and wilt can result from several root diseases, often favoured by cold, wet growing conditions. Root colour alone does not identify the organism.',prevention:'Use clean containers and fresh growing compost where soil has caused repeated losses. Maintain suitable warmth and drainage and avoid waterlogging.'},{description:'Dark, decaying roots accompany wilt. Several diseases can cause this, often in cold, wet conditions.',prevention:'Use clean containers and fresh compost where needed. Maintain suitable warmth and drainage; avoid waterlogging.'},'Remove unconfirmed worst-disease ranking and blanket diagnosis.',['https://www.rhs.org.uk/disease/root-rots']);
e(g,'gummosis',{description:'Sunken fruit lesions that ooze amber gum can occur with cucumber diseases such as scab or gummy stem blight. Cool, wet conditions favour some of these problems; gum alone does not identify the organism.'},{description:'Sunken cucumber fruit lesions may ooze amber gum. Several diseases can cause this; confirm recurring losses.'},'Preserve legacy symptom identity without equating all gummy lesions to one disease.',[],'Gummosis, black rot and stem rot overlap but are not confirmed interchangeable diagnoses. Retain separate symptoms and keys.');
e(g,'withering_of_young_fruit',{description:'Young cucurbit fruit may stop swelling and shrivel from the tip after poor pollination in varieties that require it, root stress or unsuitable temperatures. Check the crop and variety before assuming the cause.'},{description:'Young fruit stops swelling and shrivels. Check pollination needs, root health and temperatures.'},'Separate pollination-dependent crops from parthenocarpic cucumbers; remove unsupported fresh-manure mechanism.',['https://www.rhs.org.uk/vegetables/cucumbers/grow-your-own']);
e(g,'bitterness',{prevention:'Maintain steady moisture and suitable temperatures. Follow the cucumber variety instructions: greenhouse varieties grown for seedless fruit generally need protection from pollination, including removal of any male flowers they produce. Outdoor varieties needing pollination must retain male flowers. All-female flowering does not guarantee freedom from stress or bitter fruit.'},{prevention:'Follow cucumber variety instructions: keep seedless greenhouse crops unpollinated; retain male flowers where outdoor types need pollen. Keep growth steady.'},'Remove absolute all-female guarantee and preserve greenhouse/outdoor distinctions.',['https://www.rhs.org.uk/vegetables/cucumbers/grow-your-own']);
e(g,'black_rot',{treatment:'Remove infected fruit and badly affected plants. Reduce excessive humidity with ventilation and avoid prolonged surface wetness.',prevention:'Use healthy plants, clean containers and fresh growing compost where disease has recurred. Remove infected debris and keep foliage and fruit dry during watering.'},{treatment:'Remove infected fruit and badly affected plants; ventilate to reduce excessive humidity.',prevention:'Use healthy plants and clean containers. Clear infected debris and avoid wetting fruit and foliage.'},'Replace floor-spraying instruction with actionable humidity/hygiene advice; retain symptom distinction.',['https://www.rhs.org.uk/disease/grey-mould']);
e(g,'stem_rot',{treatment:'Remove badly affected plants and infected debris. Improve ventilation and avoid keeping stems and foliage wet.',prevention:'Use healthy plants, clean containers and fresh growing compost where disease has recurred. Avoid stem wounds and overcrowding.'},{treatment:'Remove badly affected plants and debris. Ventilate and avoid persistent wetness.',prevention:'Use healthy plants and clean containers; avoid stem wounds and crowding.'},'State practical hygiene directly; no assumed curative treatment for infected stems.',['https://www.rhs.org.uk/disease/grey-mould']);
e(g,'basal_stem_rot',{description:'Brown, slimy decay at the base of cucumber stems may cause wilting and collapse. Bacterial soft rot and other stem-base diseases can look alike; seek a diagnosis if losses recur.'},{description:'Brown, slimy decay at the cucumber stem base causes wilt or collapse. Several diseases can resemble this.'},'Remove unsupported equivalence of soft rot, foot rot and canker.',[],'Pathogen not confirmed from the legacy label or symptoms.');
e(g,'verticillium_wilt',{treatment:'Confirm the diagnosis where possible and remove badly affected plants. Keep remaining plants evenly watered without waterlogging; extra humidity does not cure vascular infection.',prevention:'Avoid affected soil. Grow replacements in clean containers with fresh compost isolated from contaminated ground; clean soil from tools and remove infected debris.'},{treatment:'Confirm the cause and remove badly affected plants. Maintain even moisture without waterlogging.',prevention:'Use clean containers and fresh compost isolated from affected ground; clear infected debris.'},'Replace warmth/humidity as purported wilt treatment with RHS removal and clean growing conditions.',['https://www.rhs.org.uk/disease/verticillium-wilt']);
e(g,'red_spider_mite',{treatment:'Inspect leaf undersides and introduce a suitable predatory mite early in protected crops, following supplier advice on species, temperature and humidity. Remove badly affected foliage where practical and keep plants adequately watered.',prevention:'Monitor plants in warm, dry weather. Maintain suitable humidity and ventilation without waterlogging roots or leaving foliage persistently wet.'},{treatment:'Check leaf undersides. Introduce suitable predatory mites early under cover, following supplier guidance.',prevention:'Monitor in warm, dry weather; balance root moisture, humidity and ventilation.'},'Qualify guaranteed reliable predator control and balance humidity with fungal-disease risk.',['https://www.rhs.org.uk/biodiversity/glasshouse-red-spider-mite']);
e(g,'vine_borer',{applies_to:['marrow_courgette','squash_pumpkin'],description:'A stem tunnel, entry hole and frass can point to a borer in a wilted marrow or squash, but wilting alone is not a diagnosis. The squash vine borer described in North American guidance must not be assumed to be the cause in a UK garden.',treatment:'Inspect the stem and photograph any insect or tunnel for identification. Remove plants that have collapsed beyond recovery and retain identification details before disposal.',prevention:'Check affected stems and clear badly infested crop remains. Choose prevention after the insect and its local occurrence have been confirmed.'},{description:'Stem tunnels, holes and frass suggest a borer. Do not assume North American squash vine borer in a UK garden.',treatment:'Inspect and photograph the insect or tunnel for identification; remove irrecoverable plants.',prevention:'Clear infested crop remains and base further action on confirmed identification.'},'Preserve uncertain entry; narrow hosts and flag geographic uncertainty rather than importing US treatment timing.',['https://extension.umn.edu/garden-and-home/yard-and-garden/yard-and-garden-insects/squash-vine-borers'],'The original insect identity and UK relevance remain unconfirmed.');
e(g,'storage_rot_from_stem_damage',{applies_to:['marrow_courgette','squash_pumpkin'],prevention:'Cut mature winter squash and pumpkins with a short stalk attached and carry them by the fruit. Cure in suitable warm, dry conditions, then move to a cool, dry, frost-free store with airflow. Inspect regularly and remove rotting fruit. Courgettes are harvested young for prompt use.'},{prevention:'Leave stalks attached. Cure winter squash warm and dry, then store cool, dry and frost-free; check regularly. Use young courgettes promptly.'},'Separate curing from storage and mature squash from courgette use.',['https://www.rhs.org.uk/vegetables/pumpkins/storing']);
g='lettuce_troubles';
e(g,'bolting',{description:'Lettuce produces a flowering stem as it matures. Premature bolting is encouraged by long days, heat, drought and other checks to growth, with susceptibility varying by variety and sowing season.'},{description:'Long days, heat, drought or other growth checks can trigger early flowering; susceptibility varies by variety.'},'Replace transplanting as unsupported commonest cause with season, temperature and moisture context.',[refs.bolting]);
e(g,'lettuce_root_maggot',{description:'Root-tunnelling larvae can stunt lettuce and cause wilting. Confirm that larvae are present and obtain identification: root disease, moisture stress and other insects can cause similar symptoms.',prevention:'Inspect roots when unexplained wilting occurs, remove affected crop remains and use healthy plants and clean growing media for protected crops.'},{description:'Root-tunnelling larvae may cause lettuce wilt and stunting. Inspect roots and confirm the insect.',prevention:'Inspect unexplained wilt, clear affected debris and use healthy plants and clean growing media.'},'Remove unverified chrysanthemum-host assertion and arbitrary one-year planting restriction.',[],'The legacy association with chrysanthemum stool miner is retained in the change record but was not confirmed by RHS-first research.');
