for(const key of ['drooping_leaves','bolting','saddleback','set_division','bull_neck_thick_neck','downy_mildew','shanking','neck_rot','birds_pulling_sets'])e(g,key,{applies_to:['onion_shallot']},{},'This entry describes bulb onions/sets or their storage; prevent misapplication to leeks and garlic.',[]);
e(g,'leek_moth',{applies_to:['leek','onion_shallot','garlic']},{},'Reflect RHS allium host range while keeping leek cutback treatment explicitly leek-specific.',['https://www.rhs.org.uk/biodiversity/leek-moth']);
e(g,'set_division',{description:'Some onion sets develop two or more bulbs. Large sets and growth checks can contribute. Distinguish this from the normal multiplication of shallots, which form clusters of daughter bulbs.',prevention:'Use sound onion sets of a suitable size, plant in season and maintain steady growth. Expect shallots to divide naturally.'},{description:'Onion sets may form twin bulbs; large sets and growth checks can contribute. Shallots naturally form clusters.',prevention:'Use suitable onion sets, plant in season and maintain steady growth. Shallot division is normal.'},'Preserve onion/shallot distinction within the combined crop record.',['https://www.rhs.org.uk/vegetables/onions/grow-your-own','https://www.rhs.org.uk/vegetables/shallots/grow-your-own']);
e(g,'shanking',{description:'A slimy, foul-smelling decay inside onion scales can indicate bacterial soft rot. Leaves may yellow and collapse. Similar bulb rots need diagnosis if losses recur.',treatment:'Remove rotting bulbs promptly and keep them out of storage.',prevention:'Avoid bulb injury and waterlogging. Dry harvested bulbs thoroughly and store only sound bulbs with good airflow; inspect regularly and remove decay.'},{description:'Yellowing, collapsing leaves and foul-smelling slime inside onion scales suggest soft rot.',treatment:'Remove rotten bulbs promptly; keep them out of storage.',prevention:'Avoid wounds and waterlogging. Dry sound bulbs well, store with airflow and inspect regularly.'},'Replace unsupported disease ranking and unspecified several-year ban with root/bulb hygiene.',[],'Shanking retained as a legacy symptom name; no single organism inferred.');
e(g,'birds_pulling_sets',{prevention:'Firm onion sets at their normal planting depth. Use securely supported netting until sets have rooted and resist pulling, checking regularly that wildlife cannot become trapped.'},{prevention:'Firm sets at normal depth and guard with secure netting until rooted. Check for trapped wildlife.'},'Replace arbitrary leaf-height threshold with the actual purpose: establishment and anchorage.',['https://www.rhs.org.uk/vegetables/onions/grow-your-own']);
g='spinach_troubles';
e(g,'downy_mildew',{applies_to:['spinach']},{},'The spinach-specific downy mildew diagnosis is not a generic disease identity for leaf beet.',['https://www.vegetables.cornell.edu/pest-management/disease-factsheets/spinach-downy-mildew/']);
e(g,'bolting',{description:'True spinach can flower prematurely in long days and warm weather, especially when drought or other checks stress the plants. Once a flowering stem develops, leaf quality usually declines.'},{description:'Long days and warm weather encourage true spinach to bolt, especially after drought or other growth checks.'},'Restore day-length context; avoid asserting inevitable bolting after any nutrient shortage.',[refs.bolting]);
g='tomato_troubles';
e(g,'leaf_roll',{description:'Tomato leaves often roll because of temperature fluctuations, water stress or heavy leaf removal. Firm, normally coloured leaves on a vigorous plant may show harmless physiological rolling, but distortion with mottling, stunting, pests or stem injury needs investigation.'},{description:'Leaf rolling is often physiological. Check water and temperature; investigate mottling, stunting, pests or severe distortion.'},'Remove false blanket assurance that tomato rolled leaves cannot indicate disease.',[refs.tomato]);
e(g,'virus',{treatment:'Remove confirmed or strongly suspected virus-affected plants. Clean hands and tools before handling healthy plants; extra feeding does not cure infection.'},{treatment:'Remove affected plants and clean hands and tools before handling healthy plants.'},'Remove feeding as an implied virus remedy; retain hygiene.',['https://www.rhs.org.uk/disease/tomato-viruses']);
e(g,'root_rot',{description:'Poor drainage can favour root disease. Roots may become brown, decayed or corky, and plants wilt, especially in warm weather. Similar symptoms have several causes; seek a diagnosis when losses recur.'},{description:'Brown, decayed or corky roots accompany wilting. Poor drainage favours some root diseases; confirm recurring losses.'},'Correct malformed roots-cannot-be-cured sentence and avoid a single disease diagnosis.',[refs.tomato]);
e(g,'magnesium_deficiency',{description:'Yellowing between greener veins usually starts on older tomato leaves and may later turn brown. Magnesium deficiency is one possible cause; excessive potassium can reduce magnesium uptake, but ordinary feeding does not always make the problem worse.'},{description:'Older leaves yellow between green veins and may turn brown. Confirm magnesium deficiency and review feeding.'},'Remove blanket statement that standard feeding worsens deficiency.',[refs.nutrients]);
e(g,'blossom_end_rot',{description:'A dark, sunken, leathery patch forms at the blossom end of fruit. This physiological disorder reflects inadequate calcium reaching the developing fruit, often after irregular water supply; it does not necessarily mean the soil lacks calcium.',treatment:'Affected tissue will not recover. Remove spoiled fruit and keep root moisture steady to protect later fruit.',prevention:'Water consistently without waterlogging, use sufficient root space and feed at the recommended rate. Avoid large swings between dry compost and heavy watering.'},{description:'A dark, sunken blossom-end patch develops when too little calcium reaches the fruit, often after irregular watering.',treatment:'Spoiled tissue will not recover. Remove affected fruit and stabilise watering.',prevention:'Keep roots evenly moist, provide adequate root space and avoid overfeeding.'},'Explain calcium transport and practical prevention without prescribing untested nutrient doses.',['https://www.rhs.org.uk/problems/blossom-end-rot']);
e(g,'blossom_drop',{description:'Flowers may wither and fall before fruit sets when pollination fails or plants are stressed. Excess heat, cold, unsuitable humidity and irregular root moisture can all contribute.'},{description:'Flowers wither and fall after failed pollination or stress from heat, cold, humidity or irregular watering.'},'Remove single dryness-cause diagnosis.',['https://www.rhs.org.uk/vegetables/tomatoes/grow-your-own']);
e(g,'split_fruit',{description:'Fruit skin may split after rapid swelling, often when heavy rain or watering follows a dry period. Both outdoor and greenhouse tomatoes can be affected.'},{},'Remove flavour digression that conflicts with steady-watering prevention.',['https://www.rhs.org.uk/problems/fruit-splitting-and-cracking']);
e(g,'hollow_fruit',{prevention:'Maintain steady root moisture, avoid temperature extremes and assist pollination by gently tapping flowering trusses when needed. Feed at the recommended rate and prevent herbicide drift or contamination.'},{prevention:'Keep moisture and temperature steady, assist pollen release and feed appropriately. Prevent herbicide contamination.'},'Replace circular avoid-the-listed-factors instruction with practical actions.',['https://www.rhs.org.uk/vegetables/tomatoes/grow-your-own']);
g='turnip_swede_radish_troubles';
for(const key of ['bolting_winter_radish','woody_hollow_or_soft_radish_roots'])e(g,key,{applies_to:['radish']},{},'Restrict explicitly radish-specific advice; retain summer/winter distinctions.',[]);
e(g,'boron_deficiency_brown_heart',{applies_to:['turnip','swede'],prevention:'Confirm the deficiency with soil-test-based advice before adding boron. Use any suitable organic nutrient amendment only at the advised rate: the margin between deficiency and toxic excess is narrow.'},{prevention:'Confirm deficiency and use soil-test-based advice. Follow the advised rate carefully; excess boron is toxic.'},'Retain essential overdose warning while removing editorial history and narrowing to described hosts.',[refs.nutrients]);
// Evidence substitutions for unavailable RHS profiles and additional diagnostic checks.
for(const job of edits){job.sources=job.sources.map(url=>({'https://www.rhs.org.uk/disease/violet-root-rot':'https://horticulture.ahdb.org.uk/knowledge-library/violet-root-rot','https://www.rhs.org.uk/disease/root-rots':'https://www.rhs.org.uk/soil-composts-mulches/waterlogging-flooding','https://www.rhs.org.uk/disease/leaf-spots':'https://extension.psu.edu/cercospora-leaf-spot-on-table-beets'}[url]??url));if(['mice','birds'].includes(job.key)&&job.reason.startsWith('Correct pea-only'))job.sources=[];}
e('brassica_troubles','black_rot',{description:'Yellow V-shaped areas spreading inward from leaf edges, blackened veins and stunted or wilting growth can indicate bacterial black rot. Cut stems may show dark vascular tissue. Warm, wet weather favours spread.',prevention:'Use healthy seed and transplants, remove infected crop debris, rotate crops and avoid splashing or handling plants when foliage is wet.'},{description:'Yellow V-shaped patches spread inward from leaf edges; veins darken and growth is checked. Warm, wet weather favours spread.',prevention:'Use healthy seed and transplants, clear infected debris, rotate and avoid handling wet plants.'},'Add useful characteristic diagnostic sign and replace contradictory None/rotate prevention.',['https://potatoes.ahdb.org.uk/knowledge-library/black-rot-of-brassicas-symptoms-and-biology']);
e('brassica_troubles','white_blister_white_rust',{description:'Raised white blisters develop mainly beneath leaves and can also affect stems or flower parts. Severe infection may distort growth. Several brassicas can be affected, especially in damp conditions.'},{description:'Raised white blisters, mainly beneath leaves, may also affect stems or flowers and distort growth.'},'Replace felt-like mould description and unsupported sprouts susceptibility ranking; distinguish blisters from downy mildew.',['https://projectblue.blob.core.windows.net/media/Default/Horticulture/BrassicaDiseasesGuide1719_200428_WEB.pdf']);
e('brassica_troubles','magnesium_deficiency',{description:'Yellowing between greener veins usually begins on older leaves and may later become orange, red, purple or brown. Other problems can look similar, so check growing conditions and confirm a deficiency.'},{},'Remove unsupported relative prevalence; preserve diagnostic caution.',[refs.nutrients]);
e('brassica_troubles','swede_midge',{description:'Swollen or distorted leaf stalks near the growing point and blind growth can indicate swede midge. Tiny pale larvae may be present, but other injuries can produce similar symptoms; identification is important.'},{description:'Distorted stalks near the growing point and blind growth may indicate swede midge. Look for tiny pale larvae and confirm the cause.'},'Remove unverified regional-risk and inevitable-severity claims.',[],'Species should be confirmed before management; legacy regional claims retained only in prior-byte backup.');
e('tomato_troubles','dry_set',{description:'Tiny fruitlets may stop developing after poor pollination or stress during flowering. Excess heat, dry conditions and other disorders can contribute; check the rest of the plant for symptoms too.'},{description:'Tiny fruitlets stop developing after poor pollination or flowering stress. Check heat, water supply and other symptoms.'},'Avoid single-cause certainty; tomato viruses can also cause dry set.',['https://www.rhs.org.uk/disease/tomato-viruses']);
e('tomato_troubles','greenhouse_whitefly',{visual_heading:'Tiny white insects beneath leaves',description:'Whitefly adults and immature stages feed beneath tomato leaves. Heavy infestations can weaken plants, while sticky honeydew supports sooty mould. Confirm the pest on leaf undersides before choosing a biological control.'},{},'Remove unsupported deterrent anecdote and most-widespread ranking; preserve appropriate biological control.',['https://www.rhs.org.uk/biodiversity/glasshouse-whitefly']);
